import React, { Component } from "react";

export class NewsItem extends Component {
  render() {
    let {title,description,imageUrl,newsUrl,author,date} = this.props;
    return (
      <div className="my-3">
        <div className="card" >
          <img src={imageUrl?imageUrl:"https://www.newscaststudio.com/wp-content/gallery/fox-newsroom/NCS_Fox-News-Newsroom-Studio-N_0010.JPG"} className="card-img-top" alt="..." />
          <div className="card-body">
            <h5 className="card-title">{title}...</h5>
            <p className="card-text">
             {description}...
            </p>
            <p className="card-text"><small className="text-muted">By {!author?"Unknown":author} on {newdate}</small></p>
            <a href={newsUrl} target="_blank" className="btn btn-sm btn-dark">
              Read More
            </a>
          </div>
        </div>
      </div>
    );
  }
}

export default NewsItem;
